import pandas as pd,numpy as np,json
from scipy.optimize import least_squares
def load(d):
    out=[]
    for f in sorted(os.listdir(d)):
        df=pd.read_csv(d+'/'+f).iloc[::5]; out.append((f,df))
    return out
import os
tr=load('train');va=load('val')
def sim(p,df):
    Kp,Tw,Tp,Kq,Tq,Kqp=p
    t=df.time_s.values;dt=t[1]-t[0];V=df.voltage_pu.values;th=df.bus_angle_rad.values;Vs=df.voltage_setpoint_pu.values
    P0=df.active_power_pu.values[0];Q0=df.reactive_power_pu.values[0];V0=V[0]
    x=0;y=0;z=0;P=[];Q=[]
    for i in range(len(t)):
        w=(th[i]-x)/Tw
        P.append(P0-Kp*y); Q.append(Q0+z)
        x+=dt*w; y+=dt*(w-y)/Tp
        z+=dt*(Kq*((Vs[i]-Vs[0])-(V[i]-V0))-z)/Tq if False else dt*(Kq*((Vs[i]-V[i])-(Vs[0]-V0))+Kqp*0-z)/Tq
    return np.array(P),np.array(Q)
def res(p,D):
    r=[]
    for f,df in D:
        P,Q=sim(p,df);r+=list(P-df.active_power_pu.values)+list(Q-df.reactive_power_pu.values)
    return np.array(r)
p0=[5,0.05,0.1,5,0.1,0]
s=least_squares(res,p0,args=(tr,),bounds=([0,.005,.005,0,.005,-1],[100,2,5,100,5,1]))
print(s.x,np.sqrt(np.mean(s.fun**2)))
for f,df in va:
    r=res(s.x,[(f,df)]);print(f,np.sqrt(np.mean(r**2)),df.active_power_pu.std(),df.reactive_power_pu.std())
